/**
 * Pre-loaded dilemmas for the Halcyon council, plus a builder for custom ones.
 *
 * Every scenario has exactly four options (ids A–D). Options double as vote
 * motions. `pro`/`con` sentences feed the offline scripted engine; LLM engines
 * only see label + desc. Crisis `shift` values nudge offline stances (positive =
 * the crisis makes that option more attractive). Whisper `favors` tells the
 * offline engine which option an implanted idea argues for.
 */

export const OPTION_COLORS = { A: '#4fc3f7', B: '#ffb74d', C: '#c77dff', D: '#7bd389', undecided: '#8b93a7' };

