/** A blank-slate scenario for player-written dilemmas when no model is available to design one. */
export function makeCustomScenario(text, overrides = {}) {
  const clean = text.trim().replace(/\s+/g, ' ');
  const firstSentence = clean.split(/(?<=[.!?])\s/)[0] || clean;
  const title = overrides.title || (firstSentence.length <= 48 ? firstSentence.replace(/[.!?]$/, '') : `${firstSentence.slice(0, 44).trim()}…`);
  return {
    id: 'custom',
    custom: true,
    title,
    tagline: overrides.tagline || 'A dilemma of the Chair\'s own making.',
    clock: overrides.clock || 'T-minus 24 hours',
    glyph: overrides.glyph || 'planet',
    tension: 40,
    opener: overrides.opener || 'vance',
    brief: overrides.brief || clean,
    options: overrides.options || [
      { id: 'A', label: 'Act Decisively', desc: 'Commit the station\'s full resources to an immediate, forceful response.',
        pro: ['Acting now, with everything we have, is the only way to stay ahead of this.', 'Hesitation is a decision too, and the worst one.', 'Decisive action gives our people something to rally around.'],
        con: ['Acting with everything we have leaves us nothing in reserve if we are wrong.', 'Forceful responses on incomplete facts are how small crises become catastrophes.', 'Decisiveness is just recklessness that happened to work.'] },
      { id: 'B', label: 'Contain and Buy Time', desc: 'Limit the damage, stabilize, and gather more information before committing.',
        pro: ['Containment keeps every door open while we learn what we are actually facing.', 'Stabilize first, then decide. It is how every good triage works.', 'Time is the one resource that makes every other option better.'],
        con: ['Buying time only works if the clock is on our side, and it isn\'t.', 'Containment is a word for doing nothing in an orderly way.', 'Every hour we stall, the problem grows roots.'] },
      { id: 'C', label: 'Seek Outside Help', desc: 'Call on Earth, the Consortium or our neighbors, and accept their terms.',
        pro: ['There are people out there with resources we don\'t have. Pride won\'t save us.', 'Asking for help spreads the risk and the responsibility.', 'Allies we make today are allies we have tomorrow.'],
        con: ['Help from outside always comes with a price tag, and a leash.', 'By the time outside help arrives, this will already be decided.', 'We would be handing our future to people who don\'t live here.'] },
      { id: 'D', label: 'Hold the Line', desc: 'Refuse the pressure entirely and protect the station\'s existing commitments.',
        pro: ['Our commitments exist for moments exactly like this. We keep them.', 'Refusing to be stampeded is a strength, not a weakness.', 'The status quo has kept us alive so far.'],
        con: ['Holding the line just means losing slowly.', 'The world has changed; our commitments haven\'t caught up.', 'Refusal is a luxury for people who aren\'t the ones suffering.'] },
    ],
    stances: overrides.stances || {
      vance: { position: 'A', conviction: 60, thought: 'Somebody has to take control of this.' },
      okafor: { position: 'B', conviction: 55, thought: 'Diagnose before you operate.' },
      rivet: { position: 'A', conviction: 50, thought: 'Just tell me what to fix.' },
      celeste: { position: 'D', conviction: 55, thought: 'Protect the contracts; everything else is noise.' },
      novak: { position: 'B', conviction: 50, thought: 'Let us not be hasty with something this grave.' },
      kestrel: { position: 'C', conviction: 45, thought: 'We can\'t do this alone, and upstairs won\'t share.' },
      chen: { position: 'C', conviction: 50, thought: 'Maintain equilibrium above all else.' },
    },
    crises: overrides.crises || [
      { id: 'c1', title: 'Situation Escalating', text: 'Reports confirm the situation is worsening twice as fast as projected. The window for a decision is halving.', severity: 2, shift: { A: 15, B: -15 } },
      { id: 'c2', title: 'Outside Ultimatum', text: 'An outside power has issued an ultimatum: accept their terms within the hour, or face consequences.', severity: 2, shift: { C: 10, D: 10, B: -10 } },
      { id: 'c3', title: 'Public Panic', text: 'Word has leaked to the public decks. Crowds are gathering outside the council chamber demanding answers.', severity: 2, shift: { A: 10, D: -10 } },
    ],
    whispers: overrides.whispers || [
      { text: 'There is an untried middle path: act on half the problem now, and contain the other half.', favors: 'B' },
      { text: 'A neighboring station has quietly offered help with no strings attached, if we ask before the day ends.', favors: 'C' },
    ],
    outcomes: overrides.outcomes || {
      A: { headline: 'The Council Acts', text: 'Halcyon threw everything it had at the problem. It worked, mostly, and the station spent a long year counting what it had spent to win.' },
      B: { headline: 'The Long Watch', text: 'The council chose patience. The crisis was contained, not solved, and Halcyon learned to live beside it like a sleeping animal.' },
      C: { headline: 'Help from Beyond', text: 'Help came, as it always does, with terms attached. Halcyon survived, a little less its own than before.' },
      D: { headline: 'The Line Held', text: 'The council refused to bend. The station endured on its old promises, and history is still arguing whether that was courage or stubbornness.' },
      failed: { headline: 'No Decision', text: 'The motion failed. The crisis did not wait for the council to make up its mind.' },
    },
  };
}

export function scenarioById(id) {
  return SCENARIOS.find((s) => s.id === id);
}
